import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";
import * as Tone from "tone";

const KRISHNA_IMG = "data:image/jpeg;base64,";

const SKY_GRADIENTS = [
  "linear-gradient(180deg, #f7f2e2 0%, #eaf0dd 45%, #d7e8c8 100%)",
  "linear-gradient(180deg, #f5f1e0 0%, #e3edd6 45%, #c9e2c0 100%)",
  "linear-gradient(180deg, #fbf6e6 0%, #ecefd3 40%, #cfe3bd 100%)",
  "linear-gradient(180deg, #f8f4e6 0%, #e9f1da 45%, #d3e9c6 100%)",
];

const TAGS = ["Prologue", "Chapter I · The Guide", "Chapter II · The Arrival", "Chapter III · The Invitation"];
const TOTAL = 4;

function useRandomPoints(count, topRange) {
  return useMemo(() => {
    const pts = [];
    for (let i = 0; i < count; i++) {
      pts.push({
        left: Math.random() * 100,
        top: topRange[0] + Math.random() * (topRange[1] - topRange[0]),
        delay: Math.random() * 5,
        duration: 5 + Math.random() * 4,
      });
    }
    return pts;
  }, [count, topRange]);
}

export default function JalwaInvitation() {
  const [scene, setScene] = useState(0);
  const [nameKey, setNameKey] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const touchX = useRef(null);
  const synthRef = useRef(null);
  const seqRef = useRef(null);
  const fxRef = useRef([]);

  const motes = useRandomPoints(16, [10, 60]);
  const petals = useRandomPoints(10, [50, 90]);

  const toggleAudio = useCallback(async () => {
    await Tone.start();

    if (!synthRef.current) {
      const reverb = new Tone.Reverb({ decay: 4.5, wet: 0.38 }).toDestination();
      const vibrato = new Tone.Vibrato(4.5, 0.12).connect(reverb);
      const synth = new Tone.Synth({
        oscillator: { type: "sine" },
        envelope: { attack: 0.35, decay: 0.25, sustain: 0.55, release: 1.8 },
      }).connect(vibrato);
      synth.volume.value = -17;

      // a gentle bansuri-style pentatonic phrase, with rests for breathing room
      const phrase = [
        "E4", "G4", "A4", null, "G4", "E4", "D4", null,
        "C4", "D4", "E4", null, "G4", "E4", "D4", null,
      ];
      const seq = new Tone.Sequence(
        (time, note) => {
          if (note) synth.triggerAttackRelease(note, "4n", time);
        },
        phrase,
        "4n"
      );
      seq.loop = true;
      seq.start(0);

      Tone.Transport.bpm.value = 58;

      synthRef.current = synth;
      seqRef.current = seq;
      fxRef.current = [reverb, vibrato];
    }

    if (isPlaying) {
      Tone.Transport.pause();
      setIsPlaying(false);
    } else {
      Tone.Transport.start();
      setIsPlaying(true);
    }
  }, [isPlaying]);

  useEffect(() => {
    return () => {
      Tone.Transport.stop();
      if (seqRef.current) seqRef.current.dispose();
      if (synthRef.current) synthRef.current.dispose();
      fxRef.current.forEach((node) => node.dispose());
    };
  }, []);

  const goTo = useCallback((i) => {
    setScene((current) => {
      const next = Math.max(0, Math.min(TOTAL - 1, i));
      if (next === 2 && current !== 2) {
        setNameKey((k) => k + 1);
      }
      return next;
    });
  }, []);

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "ArrowRight") goTo(scene + 1);
      if (e.key === "ArrowLeft") goTo(scene - 1);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [scene, goTo]);

  const onTouchStart = (e) => {
    touchX.current = e.touches[0].clientX;
  };
  const onTouchEnd = (e) => {
    if (touchX.current === null) return;
    const dx = e.changedTouches[0].clientX - touchX.current;
    if (Math.abs(dx) > 50) {
      if (dx < 0) goTo(scene + 1);
      else goTo(scene - 1);
    }
    touchX.current = null;
  };

  const sceneStyle = (idx) => {
    const diff = idx - scene;
    return {
      position: "absolute",
      inset: 0,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      flexDirection: "column",
      textAlign: "center",
      padding: "6vh 8vw 14vh",
      opacity: diff === 0 ? 1 : 0,
      transform: `translateX(${diff * 44}px)`,
      pointerEvents: diff === 0 ? "auto" : "none",
      transition: "opacity 0.9s ease, transform 0.9s ease",
      zIndex: diff === 0 ? 2 : 1,
    };
  };

  return (
    <div
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
      style={{
        position: "relative",
        width: "100%",
        height: "100vh",
        minHeight: 560,
        overflow: "hidden",
        background: "#f7f2e2",
        fontFamily: "'Poppins', sans-serif",
        color: "#20351f",
        userSelect: "none",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Marcellus&family=Poppins:wght@300;400;500&display=swap');

        @keyframes drift {
          0%,100%{ transform: translate(0,0); opacity:0.35; }
          50%{ transform: translate(10px,-18px); opacity:0.9; }
        }
        @keyframes petalFall {
          0%{ transform: translate(0,0) rotate(0deg); opacity:0; }
          10%{ opacity:0.8; }
          100%{ transform: translate(-24px, 90px) rotate(140deg); opacity:0; }
        }
        @keyframes sway {
          0%,100%{ transform:rotate(-1.5deg); }
          50%{ transform:rotate(1.8deg); }
        }
        @keyframes tailflick { 0%,100%{transform:rotate(6deg);} 50%{transform:rotate(-6deg);} }
        @keyframes headbob { 0%,100%{transform:rotate(0deg);} 50%{transform:rotate(-3deg);} }
        @keyframes glowPulse {
          0%,100%{ opacity:0.6; transform:scale(1); }
          50%{ opacity:0.95; transform:scale(1.08); }
        }
        @keyframes floatGuide {
          0%,100%{ transform: translateY(0); }
          50%{ transform: translateY(-10px); }
        }
        @keyframes nameIn {
          0%{ opacity:0; transform:scale(0.8) translateY(14px); letter-spacing:0.3em; }
          60%{ opacity:1; }
          100%{ opacity:1; transform:scale(1) translateY(0); letter-spacing:0.02em; }
        }
        .jalwa-btn {
          font-family:'Poppins', sans-serif;
          font-weight:500; font-size:14px; letter-spacing:0.06em;
          text-transform:uppercase; color:#fbf8ef;
          background: linear-gradient(135deg, #6d9a5f, #3f6b4f);
          border:none; padding:15px 38px; border-radius:40px; cursor:pointer;
          box-shadow: 0 8px 24px rgba(63,107,79,0.28);
          transition: transform 0.25s ease, box-shadow 0.25s ease;
        }
        .jalwa-btn:hover{ transform: translateY(-2px); box-shadow: 0 12px 30px rgba(63,107,79,0.38); }
        .jalwa-btn:focus-visible{ outline:3px solid #274a35; outline-offset:3px; }
        .jalwa-dot { width:10px; height:10px; border-radius:50%; background:rgba(39,74,53,0.2);
          border:1px solid rgba(39,74,53,0.35); cursor:pointer; padding:0; transition:all 0.3s ease; }
        .jalwa-dot.active { background:#c9a15a; border-color:#c9a15a; transform:scale(1.3); box-shadow:0 0 10px rgba(201,161,90,0.5); }
        .jalwa-dot:focus-visible{ outline:2px solid #274a35; outline-offset:2px; }
        .jalwa-arrow {
          position:absolute; top:50%; transform:translateY(-50%);
          width:46px; height:46px; border-radius:50%;
          background: rgba(255,255,255,0.55); border:1px solid rgba(63,107,79,0.3);
          color:#3f6b4f; font-size:18px; display:flex; align-items:center; justify-content:center;
          cursor:pointer; z-index:20; transition: opacity 0.3s ease, transform 0.2s ease;
          box-shadow: 0 4px 14px rgba(63,107,79,0.15);
        }
        .jalwa-arrow:hover{ transform: translateY(-50%) scale(1.08); }
        .jalwa-arrow[disabled]{ opacity:0; pointer-events:none; }
        @media (max-width: 720px){ .jalwa-arrow{ display:none; } }
        @media (prefers-reduced-motion: reduce){
          .jalwa-anim, .jalwa-anim * { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
        }
      `}</style>

      {/* Sky */}
      <div style={{ position: "absolute", inset: 0, background: SKY_GRADIENTS[scene], transition: "background 1.4s ease" }} />

      {/* Sun glow */}
      <div
        style={{
          position: "absolute", top: "6%", right: "10%", width: 150, height: 150, borderRadius: "50%",
          background: "radial-gradient(circle at 40% 40%, #fff6df, #f3d99a 55%, transparent 78%)",
          boxShadow: "0 0 90px 30px rgba(243,217,154,0.35)",
          opacity: scene === 2 ? 0.55 : 0.9,
          transform: scene === 2 ? "translateY(-6px) scale(0.9)" : "translateY(0) scale(1)",
          transition: "opacity 1s ease, transform 1.2s ease",
        }}
      />

      {/* Drifting light motes */}
      <div className="jalwa-anim" style={{ position: "absolute", inset: 0 }}>
        {motes.map((s, i) => (
          <span
            key={i}
            style={{
              position: "absolute", width: 4, height: 4, borderRadius: "50%",
              background: "#e9d9a6", boxShadow: "0 0 6px 2px rgba(233,217,166,0.6)",
              left: `${s.left}%`, top: `${s.top}%`,
              animation: `drift ${s.duration}s ease-in-out ${s.delay}s infinite`,
            }}
          />
        ))}
      </div>

      {/* Falling petals */}
      <div className="jalwa-anim" style={{ position: "absolute", inset: 0, overflow: "hidden" }}>
        {petals.map((p, i) => (
          <span
            key={i}
            style={{
              position: "absolute", width: 8, height: 8, borderRadius: "60% 10% 60% 10%",
              background: "#e7b98c",
              left: `${p.left}%`, top: `${p.top}%`,
              animation: `petalFall ${p.duration + 3}s ease-in ${p.delay}s infinite`,
            }}
          />
        ))}
      </div>

      {/* Hills / foliage base */}
      <svg style={{ position: "absolute", bottom: 0, left: 0, width: "100%", height: "42%" }} viewBox="0 0 1200 400" preserveAspectRatio="none">
        <path d="M0,400 L0,260 Q150,190 320,240 Q520,300 700,220 Q900,150 1200,230 L1200,400 Z" fill="#6f9660" opacity="0.55" />
        <path d="M0,400 L0,310 Q220,260 420,300 Q640,340 860,290 Q1040,250 1200,300 L1200,400 Z" fill="#4c7a45" opacity="0.85" />
      </svg>

      {/* Trees */}
      <svg className="jalwa-anim" style={{ position: "absolute", left: "-2%", bottom: 0, width: "26vw", minWidth: 180 }} viewBox="0 0 220 320">
        <rect x="98" y="150" width="16" height="170" fill="#5a4632" />
        <g style={{ transformOrigin: "bottom center", animation: "sway 6s ease-in-out infinite" }}>
          <ellipse cx="60" cy="120" rx="60" ry="46" fill="#6fa15e" />
          <ellipse cx="140" cy="100" rx="66" ry="50" fill="#7fb46c" />
          <ellipse cx="105" cy="70" rx="55" ry="42" fill="#94c67f" />
          <ellipse cx="150" cy="150" rx="50" ry="38" fill="#6fa15e" />
        </g>
      </svg>
      <svg className="jalwa-anim" style={{ position: "absolute", right: "-4%", bottom: 0, width: "30vw", minWidth: 200 }} viewBox="0 0 220 320">
        <rect x="100" y="160" width="18" height="160" fill="#5a4632" />
        <g style={{ transformOrigin: "bottom center", animation: "sway 7s ease-in-out infinite" }}>
          <ellipse cx="150" cy="130" rx="62" ry="48" fill="#6fa15e" />
          <ellipse cx="70" cy="110" rx="60" ry="46" fill="#7fb46c" />
          <ellipse cx="110" cy="75" rx="56" ry="44" fill="#94c67f" />
          <ellipse cx="60" cy="160" rx="46" ry="34" fill="#6fa15e" />
        </g>
      </svg>

      {/* Cows */}
      <svg className="jalwa-anim" style={{ position: "absolute", left: "8%", bottom: "6%", width: "11vw", minWidth: 110, maxWidth: 150 }} viewBox="0 0 200 130">
        <g style={{ transformOrigin: "60% 90%", animation: "headbob 5s ease-in-out infinite" }}>
          <ellipse cx="34" cy="70" rx="26" ry="20" fill="#fffaf0" />
          <path d="M14,58 Q8,44 20,42 Q22,50 20,58 Z" fill="#fffaf0" />
          <path d="M52,58 Q60,44 48,42 Q46,50 48,58 Z" fill="#fffaf0" />
          <ellipse cx="26" cy="72" rx="3" ry="4" fill="#3a2c1c" />
        </g>
        <ellipse cx="110" cy="80" rx="70" ry="34" fill="#fffdf6" />
        <ellipse cx="90" cy="70" rx="14" ry="10" fill="#c9a15a" opacity="0.45" />
        <ellipse cx="140" cy="90" rx="16" ry="11" fill="#c9a15a" opacity="0.45" />
        <rect x="60" y="100" width="10" height="26" rx="4" fill="#fffaf0" />
        <rect x="150" y="100" width="10" height="26" rx="4" fill="#fffaf0" />
        <rect x="100" y="105" width="10" height="24" rx="4" fill="#fffaf0" />
        <rect x="130" y="105" width="10" height="24" rx="4" fill="#fffaf0" />
        <path style={{ transformOrigin: "top center", animation: "tailflick 3.2s ease-in-out infinite" }} d="M178,72 Q195,90 186,115" stroke="#fffaf0" strokeWidth="4" fill="none" strokeLinecap="round" />
      </svg>
      <svg className="jalwa-anim" style={{ position: "absolute", right: "10%", bottom: "6%", width: "9vw", minWidth: 90, maxWidth: 130, opacity: 0.95 }} viewBox="0 0 200 130">
        <g style={{ transformOrigin: "60% 90%", animation: "headbob 6s ease-in-out infinite" }}>
          <ellipse cx="34" cy="70" rx="24" ry="18" fill="#f3ead6" />
          <ellipse cx="26" cy="72" rx="3" ry="4" fill="#3a2c1c" />
        </g>
        <ellipse cx="108" cy="80" rx="64" ry="30" fill="#f7f0dd" />
        <rect x="60" y="98" width="9" height="24" rx="4" fill="#f3ead6" />
        <rect x="145" y="98" width="9" height="24" rx="4" fill="#f3ead6" />
        <path style={{ transformOrigin: "top center", animation: "tailflick 3.2s ease-in-out infinite" }} d="M172,70 Q188,86 180,108" stroke="#f3ead6" strokeWidth="3.5" fill="none" strokeLinecap="round" />
      </svg>

      {/* Flute audio toggle */}
      <button
        onClick={toggleAudio}
        aria-label={isPlaying ? "Mute flute melody" : "Play flute melody"}
        style={{
          position: "absolute", top: 18, left: 18, zIndex: 25,
          width: 42, height: 42, borderRadius: "50%",
          background: "rgba(255,255,255,0.6)", border: "1px solid rgba(63,107,79,0.3)",
          display: "flex", alignItems: "center", justifyContent: "center",
          cursor: "pointer", boxShadow: "0 4px 14px rgba(63,107,79,0.15)",
          transition: "transform 0.2s ease",
        }}
      >
        <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="#3f6b4f" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
          {isPlaying ? (
            <>
              <path d="M11 5 6 9H3v6h3l5 4V5z" />
              <path d="M15.5 8.5a5 5 0 0 1 0 7" />
              <path d="M18 6a9 9 0 0 1 0 12" />
            </>
          ) : (
            <>
              <path d="M11 5 6 9H3v6h3l5 4V5z" />
              <line x1="16" y1="9" x2="22" y2="15" />
              <line x1="22" y1="9" x2="16" y2="15" />
            </>
          )}
        </svg>
      </button>

      {/* Chapter tag */}
      <span style={{
        position: "absolute", top: 22, left: "50%", transform: "translateX(-50%)",
        fontSize: 11, letterSpacing: "0.18em", textTransform: "uppercase", color: "#4c7a45", opacity: 0.9, zIndex: 20,
      }}>
        {TAGS[scene]}
      </span>

      {/* Scenes */}
      <div style={{ position: "absolute", inset: 0 }}>

        {/* Scene 0: Prologue */}
        <div style={sceneStyle(0)}>
          <p style={{ fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", letterSpacing: "0.12em", color: "#8a6a2f", fontSize: "clamp(13px,2vw,16px)", marginBottom: 14, opacity: 0.9 }}>
            A story from Vrindavan
          </p>
          <h1 style={{ fontFamily: "'Marcellus', serif", fontWeight: 400, lineHeight: 1.08, fontSize: "clamp(34px,6.4vw,64px)", color: "#22391f", textShadow: "0 2px 18px rgba(255,255,255,0.5)", margin: 0 }}>
            A little one<br />has arrived
          </h1>
          <p style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(16px,2.4vw,22px)", color: "#4c7a45", marginTop: 16, maxWidth: 480 }}>
            Under a canopy of green, beside the cows and the tulsi garden,<br />a small blessing has come home. You are part of this story.
          </p>
          <button className="jalwa-btn" style={{ marginTop: 40 }} onClick={() => goTo(1)}>Begin the Story</button>
        </div>

        {/* Scene 1: The Guide */}
        <div style={sceneStyle(1)}>
          <p style={{ fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", letterSpacing: "0.12em", color: "#8a6a2f", fontSize: "clamp(13px,2vw,16px)", marginBottom: 14, opacity: 0.9 }}>
            Chapter I · The Guide
          </p>
          <div className="jalwa-anim" style={{ position: "relative", width: "clamp(170px,26vw,240px)", height: "clamp(170px,26vw,240px)", marginBottom: 22, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <div style={{
              position: "absolute", inset: "-22%", borderRadius: "50%",
              background: "radial-gradient(circle, rgba(201,161,90,0.35), rgba(111,161,94,0.3) 45%, transparent 72%)",
              filter: "blur(4px)", animation: "glowPulse 5s ease-in-out infinite",
            }} />
            <img
              src={KRISHNA_IMG}
              alt="Baby Krishna smiling in a lush green garden, holding fruit"
              style={{
                position: "relative", width: "100%", height: "100%", objectFit: "cover", borderRadius: "50%",
                border: "3px solid #c9a15a",
                boxShadow: "0 0 30px rgba(201,161,90,0.4), 0 0 70px rgba(111,161,94,0.35)",
                animation: "floatGuide 6s ease-in-out infinite",
              }}
            />
          </div>
          <p style={{ fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", fontSize: "clamp(20px,3.2vw,30px)", maxWidth: 560, lineHeight: 1.5, margin: 0, color: "#22391f" }}>
            "Come a little closer,<br />someone new has joined our story in <span style={{ color: "#8a6a2f", fontStyle: "normal" }}>Vrindavan</span>."
          </p>
          <button className="jalwa-btn" style={{ marginTop: 40 }} onClick={() => goTo(2)}>Follow Gopal</button>
        </div>

        {/* Scene 2: The Arrival */}
        <div style={sceneStyle(2)}>
          <p style={{ fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", letterSpacing: "0.12em", color: "#8a6a2f", fontSize: "clamp(13px,2vw,16px)", marginBottom: 2, opacity: 0.85 }}>
            Chapter II · The Arrival
          </p>
          <p style={{ fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", letterSpacing: "0.12em", color: "#8a6a2f", fontSize: "clamp(13px,2vw,16px)", marginBottom: 14, opacity: 0.85 }}>
            her name is
          </p>
          <h1
            key={nameKey}
            style={{
              fontFamily: "'Marcellus', serif", fontSize: "clamp(50px,11vw,120px)", color: "#3f6b4f",
              letterSpacing: "0.02em", textShadow: "0 2px 20px rgba(255,255,255,0.6)", margin: 0,
              animation: "nameIn 1.4s cubic-bezier(.2,.9,.25,1) 0.1s forwards", opacity: 0,
            }}
          >
            Ridhav
          </h1>

          <svg style={{ width: "clamp(60px,8vw,90px)", margin: "20px auto 6px", opacity: 0.9 }} viewBox="0 0 100 60">
            <path d="M50,58 C40,40 20,30 6,10" stroke="#c9a15a" strokeWidth="2" fill="none" />
            <path d="M50,58 C60,40 80,30 94,10" stroke="#c9a15a" strokeWidth="2" fill="none" />
            <ellipse cx="50" cy="18" rx="10" ry="14" fill="none" stroke="#3f6b4f" strokeWidth="2" />
            <circle cx="50" cy="18" r="4" fill="#3f6b4f" />
          </svg>
          <p style={{ fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", color: "#4c7a45", fontSize: "clamp(15px,2.2vw,19px)", marginTop: 14 }}>
            meaning, "blessed with prosperity and abundance"
          </p>
          <button className="jalwa-btn" style={{ marginTop: 36 }} onClick={() => goTo(3)}>See you there</button>
        </div>

        {/* Scene 3: The Invitation */}
        <div style={sceneStyle(3)}>
          <p style={{ fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", letterSpacing: "0.12em", color: "#8a6a2f", fontSize: "clamp(13px,2vw,16px)", marginBottom: 14, opacity: 0.9 }}>
            Chapter III · The Invitation
          </p>
          <div style={{
            background: "rgba(255,255,255,0.55)", border: "1px solid rgba(201,161,90,0.4)",
            backdropFilter: "blur(6px)", borderRadius: 20, padding: "clamp(24px,4vw,40px) clamp(22px,5vw,52px)", maxWidth: 480,
            boxShadow: "0 10px 40px rgba(63,107,79,0.12)",
          }}>
            <div style={{ fontFamily: "'Marcellus', serif", fontSize: "clamp(24px,4vw,32px)", color: "#3f6b4f", marginBottom: 6 }}>
              Jalwa Ceremony
            </div>
            <div style={{ fontFamily: "'Cormorant Garamond', serif", fontStyle: "italic", color: "#8a6a2f", fontSize: "clamp(15px,2vw,18px)", marginBottom: 22 }}>
              the naming &amp; blessing of Ridhav Khandelwal
            </div>

            <DetailRow
              label="Date" value="Friday, 10th July 2026"
              icon={<><rect x="3" y="5" width="18" height="16" rx="2" /><path d="M3 10h18M8 3v4M16 3v4" /></>}
            />
            <DetailRow
              label="Time" value="7:00 PM onwards"
              icon={<><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 3" /></>}
            />
            <DetailRow
              label="Venue" value="Shri Khole Ke Hanuman Ji Temple, Jaipur"
              icon={<><path d="M12 21s7-6.5 7-12a7 7 0 1 0-14 0c0 5.5 7 12 7 12z" /><circle cx="12" cy="9" r="2.4" /></>}
            />

            <a
              href="https://maps.app.goo.gl/wiAmkoUr9oxk99qu5"
              target="_blank"
              rel="noopener noreferrer"
              style={{
                display: "inline-flex", alignItems: "center", gap: 8,
                marginTop: 16, padding: "9px 20px", borderRadius: 30,
                background: "rgba(63,107,79,0.1)", border: "1px solid rgba(63,107,79,0.35)",
                color: "#3f6b4f", fontSize: 12.5, fontWeight: 500, letterSpacing: "0.04em",
                textDecoration: "none", textTransform: "uppercase",
              }}
            >
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#3f6b4f" strokeWidth="2">
                <path d="M12 21s7-6.5 7-12a7 7 0 1 0-14 0c0 5.5 7 12 7 12z" /><circle cx="12" cy="9" r="2.4" />
              </svg>
              Get Directions
            </a>

            <p style={{ marginTop: 18, fontSize: 12.5, color: "#4c7a45", opacity: 0.9 }}>
              With love, the Khandelwal family
            </p>
          </div>
        </div>

      </div>

      {/* Arrows */}
      <button className="jalwa-arrow" style={{ left: 22 }} onClick={() => goTo(scene - 1)} disabled={scene === 0} aria-label="Previous">←</button>
      <button className="jalwa-arrow" style={{ right: 22 }} onClick={() => goTo(scene + 1)} disabled={scene === TOTAL - 1} aria-label="Next">→</button>

      {/* Dots */}
      <div style={{ position: "absolute", left: "50%", bottom: 26, transform: "translateX(-50%)", display: "flex", gap: 14, zIndex: 20 }}>
        {Array.from({ length: TOTAL }).map((_, i) => (
          <button
            key={i}
            className={`jalwa-dot${i === scene ? " active" : ""}`}
            onClick={() => goTo(i)}
            aria-label={`Go to ${TAGS[i]}`}
          />
        ))}
      </div>
    </div>
  );
}

function DetailRow({ label, value, icon }) {
  return (
    <div style={{ display: "flex", alignItems: "flex-start", gap: 14, textAlign: "left", padding: "10px 0", borderTop: "1px solid rgba(201,161,90,0.25)" }}>
      <svg style={{ width: 20, height: 20, flexShrink: 0, marginTop: 2 }} viewBox="0 0 24 24" fill="none" stroke="#3f6b4f" strokeWidth="1.6">
        {icon}
      </svg>
      <div>
        <div style={{ fontSize: 11, letterSpacing: "0.1em", textTransform: "uppercase", color: "#8a6a2f", opacity: 0.9 }}>{label}</div>
        <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "clamp(16px,2.2vw,19px)", color: "#22391f" }}>{value}</div>
      </div>
    </div>
  );
}